73	export function allocateSeriesColors(inputs: StatsSeriesColorInput[], palettes: StatsSeriesPalettes) {
74	    const usedColors = new Set<string>();
75	    const colorsByIdentity = new Map<string, string>();
76	    const takenByGroup = new Map<string, number>();
77	    // Neutral entries are allocated last so an agent family never loses its color to a shared one.
78	    const ordered = [
79	        ...inputs.filter(({ group }) => group !== NEUTRAL_GROUP),
80	        ...inputs.filter(({ group }) => group === NEUTRAL_GROUP),
81	    ];
82	
83	    for (const { group, key } of ordered) {
84	        const palette = group === NEUTRAL_GROUP ? palettes.neutral : palettes.groups[group] ?? palettes.neutral;
85	        let index = takenByGroup.get(group) ?? 0;
86	        let color = palette[index];
87	        while (color !== undefined && usedColors.has(normalizedCssColor(color))) {
88	            index += 1;
89	            color = palette[index];
90	        }
91	        takenByGroup.set(group, index + 1);
92	        let assigned = color ?? randomCssColor();
93	
94	        while (usedColors.has(normalizedCssColor(assigned))) assigned = randomCssColor();
95	
96	        usedColors.add(normalizedCssColor(assigned));
97	        colorsByIdentity.set(key, assigned);
98	    }
99	
100	    return colorsByIdentity;
101	}
