117	        if (controls.startUtc && controls.endUtc && Date.parse(controls.startUtc) > Date.parse(controls.endUtc)) {
118	            throw new Error('Stats start date must not be after end date');
119	        }
120	        // A display-only control changes no aggregated row, so keep the existing rows object
121	        // instead of paying for a full rebuild.
122	        const changedKeys = Object.keys(changes) as (keyof StatsControls)[];
123	        const displayOnly = changedKeys.length > 0
124	            && changedKeys.every((key) => key === 'shortTokenCounts');
125	        if (!this.source || displayOnly) {
126	            this.publish({ ...this.snapshot, controls });
127	            return;
128	        }
129	
130	        this.publish(buildSnapshot(this.source, controls));
131	    }
132	
133	    private async load(binding: StatsProjectBinding, agentProfiles: AgentProfile[], signal: AbortSignal) {
134	        const revision = ++this.loadRevision;
135	        const isCurrent = () => this.isCurrentLoad(revision, binding, signal);
136	        this.publish({ ...this.snapshot, error: null, rows: [], status: 'loading' });
137	        try {
138	            const source = await this.loader.loadSource(binding, this.cards, signal, isCurrent);
139	            if (!source) return;
140	            this.source = { ...source, agentProfiles };
141	            this.publish(buildSnapshot(this.source, this.snapshot.controls));
142	        } catch (error) {
143	            if (!isCurrent()) return;
144	            const normalizedError = error instanceof Error ? error : new Error(String(error));
145	            this.source = null;
146	            this.publish({ ...this.snapshot, error: normalizedError, rows: [], status: 'error' });
147	        }
148	    }
149	
150	    private isCurrentLoad(revision: number, binding: StatsProjectBinding, signal: AbortSignal) {
151	        return !signal.aborted && this.isOpen && revision === this.loadRevision && binding === this.binding;
152	    }
153	
154	    private publish(snapshot: ProjectStatsSnapshot) {
155	        this.snapshot = snapshot;
156	        this.dispatchEvent(new Event('changed'));
157	    }
158	}
